from collections import OrderedDict

class LRUCache:
    """Least Recently Used cache backed by OrderedDict."""

    def __init__(self, capacity):
        """Initialize cache with max capacity."""
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        """Get value for key, or None if not found. Marks key as recently used."""
        if key not in self.cache:
            return None
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        """Put key-value pair in cache. Evicts LRU item if at capacity."""
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value

        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

    def __len__(self):
        return len(self.cache)

    def __contains__(self, key):
        return key in self.cache


# Example usage
if __name__ == "__main__":
    lru = LRUCache(2)
    lru.put(1, "a")
    lru.put(2, "b")
    print(lru.get(1))  # "a" (marks 1 as recently used)
    lru.put(3, "c")   # Evicts key 2 (least recently used)
    print(lru.get(2))  # None
    print(lru.get(3))  # "c"
```

The class uses `OrderedDict.move_to_end()` to mark accessed keys as recently used, and `popitem(last=False)` to evict the least recently used (oldest) item when capacity is exceeded. Want me to save this to a file?

```python
from collections import OrderedDict

class LRUCache:
    """Least Recently Used cache backed by OrderedDict."""

    def __init__(self, capacity):
        """Initialize cache with max capacity."""
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        self.capacity = capacity
        self.cache = OrderedDict()
        self.hits = 0
        self.misses = 0

    def get(self, key):
        """Get value for key, or None if not found. Marks key as recently used."""
        if key not in self.cache:
            self.misses += 1
            return None
        self.hits += 1
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        """Put key-value pair in cache. Evicts LRU item if at capacity."""
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value

        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

    def stats(self):
        """Return cache statistics: hits, misses, and current size."""
        return {
            "hits": self.hits,
            "misses": self.misses,
            "size": len(self.cache),
            "capacity": self.capacity
        }

    def __len__(self):
        return len(self.cache)

    def __contains__(self, key):
        return key in self.cache


# Example usage
if __name__ == "__main__":
    lru = LRUCache(2)
    lru.put(1, "a")
    lru.put(2, "b")
    lru.get(1)     # hit
    lru.put(3, "c")
    lru.get(2)     # miss
    lru.get(3)     # hit

    print(lru.stats())
    # {'hits': 2, 'misses': 1, 'size': 2, 'capacity': 2}
```

Added instance variables `hits` and `misses` tracked in `get()`, plus a `stats()` method returning hits, misses, current size, and capacity.
